import{_ as a,o as n,c as t,a6 as s}from"./chunks/framework.DNkVJs23.js";const h=JSON.parse('{"title":"Questions fréquentes","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/fr/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/fr/faq/"}],["meta",{"property":"og:title","content":"Questions fréquentes | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Données Monster Hunter et recherche de sets pour Wilds, Rise avec Sunbreak et World avec Iceborne."}]]},"headers":[],"relativePath":"fr/faq/index.md","filePath":"fr/faq/index.md"}'),r={name:"fr/faq/index.md"};function o(i,e,l,p,c,u){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="questions-frequentes" tabindex="-1">Questions fréquentes <a class="header-anchor" href="#questions-frequentes" aria-label="Permalink to &quot;Questions fréquentes&quot;">​</a></h1><h2 id="quels-jeux-sont-pris-en-charge" tabindex="-1">Quels jeux sont pris en charge ? <a class="header-anchor" href="#quels-jeux-sont-pris-en-charge" aria-label="Permalink to &quot;Quels jeux sont pris en charge ?&quot;">​</a></h2><p>Wilds, Rise avec Sunbreak et World avec Iceborne. Les données et mécaniques de chaque jeu sont séparées ; le jeu se choisit depuis l’accueil.</p><h2 id="ou-telecharger-l-application" tabindex="-1">Où télécharger l’application ? <a class="header-anchor" href="#ou-telecharger-l-application" aria-label="Permalink to &quot;Où télécharger l’application ?&quot;">​</a></h2><p>Android est disponible sur <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a> et HarmonyOS sur <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. La version iOS est en préparation. Consultez les <a href="./../#download">téléchargements</a> ; la disponibilité dépend de la région et de l’appareil.</p><h2 id="peut-on-l-utiliser-hors-ligne" tabindex="-1">Peut-on l’utiliser hors ligne ? <a class="header-anchor" href="#peut-on-l-utiliser-hors-ligne" aria-label="Permalink to &quot;Peut-on l’utiliser hors ligne ?&quot;">​</a></h2><p>Les données sont incluses dans l’application. Consultation, recherche, favoris et recherche de sets fonctionnent localement. Les liens externes et mises à jour nécessitent une connexion.</p><h2 id="comment-fonctionne-la-recherche-de-sets" tabindex="-1">Comment fonctionne la recherche de sets ? <a class="header-anchor" href="#comment-fonctionne-la-recherche-de-sets" aria-label="Permalink to &quot;Comment fonctionne la recherche de sets ?&quot;">​</a></h2><p>Indiquez les talents et niveaux requis, fixez ou excluez des équipements et limitez les joyaux à votre inventaire. Rise prend aussi en compte les talismans et armures améliorées possédés. Les résultats dépendent des données et critères ; ce n’est pas un calculateur de dégâts.</p><h2 id="quelles-langues-sont-proposees" tabindex="-1">Quelles langues sont proposées ? <a class="header-anchor" href="#quelles-langues-sont-proposees" aria-label="Permalink to &quot;Quelles langues sont proposées ?&quot;">​</a></h2><p>L’application propose 14 langues. Certains textes de jeu peuvent rester en anglais. Pour l’espagnol latino-américain, un texte manquant est recherché en espagnol d’Espagne, puis en anglais.</p><p>English · 日本語 · 简体中文 · 繁體中文 · Français · Deutsch · Italiano · 한국어 · Español (España) · Español (Latinoamérica) · Português (Brasil) · Polski · Русский · العربية</p><h2 id="est-ce-une-application-officielle" tabindex="-1">Est-ce une application officielle ? <a class="header-anchor" href="#est-ce-une-application-officielle" aria-label="Permalink to &quot;Est-ce une application officielle ?&quot;">​</a></h2><p>Non. C’est une application indépendante de fans, sans affiliation ni approbation de CAPCOM. Les illustrations et données de Monster Hunter appartiennent à CAPCOM Co., Ltd.</p>',14)])])}const f=a(r,[["render",o]]);export{h as __pageData,f as default};
